import json
schedule=[('cobalt',[0,1,2,3,4],1320,360),('reed',[0,2,4],1380,180),('plum',[1,3,5],30,150),('shell',[6],1350,90),('gold',[0],0,90),('elm',[5],60,180)]
jobs=[{'receiver':{'day':d,'minute':m}} for d,m in [(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]]
def correct(job):
 d,m=job['receiver']['day'],job['receiver']['minute']; t=d*1440+m
 covering=[]
 for i,(r,days,s,e) in enumerate(schedule):
  duration=(e-s)%1440
  for day in days:
   for week in [-1,0]:
    start=(day+7*week)*1440+s
    if start<=t<start+duration: covering.append((duration,i,r))
 return min(covering)[2] if covering else 'idle'
def receiver(job,fault):
 d,m=job['receiver']['day'],job['receiver']['minute']; covering=[]
 for i,(r,days,s,e) in enumerate(schedule):
  owner=d if fault=='day_owner' or s<e or m>=s else (d-1)%7
  clock=(s<=m<e) if s<e else (m>=s or m<e)
  if owner in days and clock: covering.append(((e-s)%1440,i,r))
 if not covering:return 'idle'
 return (min(covering,key=lambda x:x[1]) if fault=='first_match' else min(covering))[2]
witnesses={}
for fault,other in [('day_owner','first_match'),('first_match','day_owner')]:
 for d in range(7):
  for m in range(1440):
   job={'receiver':{'day':d,'minute':m}}; expected=correct(job)
   if receiver(job,fault)!=expected and receiver(job,other)==expected:
    witnesses[fault]={'job':job,'expected':expected};break
  if fault in witnesses:break
artifact={'routes':[correct(j) for j in jobs],'witnesses':witnesses}
payload=json.dumps(artifact,separators=(',',':'))
recovered=json.loads(payload)
assert set(recovered)=={'routes','witnesses'}
assert set(recovered['witnesses'])=={'day_owner','first_match'}
for fault,w in recovered['witnesses'].items():
 assert set(w)=={'job','expected'} and set(w['job'])=={'receiver'} and set(w['job']['receiver'])=={'day','minute'}
 assert receiver(w['job'],fault)!=w['expected']
 assert receiver(w['job'],'first_match' if fault=='day_owner' else 'day_owner')==w['expected']
 assert correct(w['job'])==w['expected']
for j,r in zip(jobs,recovered['routes']):assert receiver(j,'correct')==r
print(payload)

